    | Item(Int, Scores)

visit : (Scores, Cell.Handle<R>) -> Unit ! {Cell.Ops<R>} where Cell.Provider<R>
visit (End, counter) = ()
visit (Item(value, rest), counter) = {
    let before = Cell.read counter
    let ignored = Cell.write (counter, before + 1)
    visit (rest, counter)
}

