    false => match index == 1 {
        true => Send(42)
        false => Close
    }
}

run : Bool -> Replies
run start_first = resource cell<R> cursor = 0 {
    handle (session Idle) with Session {
        receive () => {
            let index = Cell.read cursor
            let ignored = Cell.write (cursor, index + 1)
            resume (script (start_first, index))
        }
        reply response => {
            let rest = resume ()
            More(response, rest)
        }
    }
}

