pub type Request = Request(Int, Bool)
pub type Steps = End
    | Step(Int, Steps)

pub type Result = Delivered(Request)
    | Rejected

effect Pipeline {
    publish : Request -> Request
}

effect Policy {
    check : Request -> Unit
}

effect Trace {
    stage : Int -> Unit
}

normalize : Request -> Request ! {Trace}
normalize (Request(priority, tagged)) = {
    let ignored = perform Trace.stage 1
    match priority == 0 {
        true => Request(1, tagged)
        false => Request(priority, tagged)
    }
}

check_policy : Request -> Request ! {Policy, Trace}
check_policy request = {
    let ignored = perform Trace.stage 2
    let ignored = perform Policy.check request
    request
}

enrich : Request -> Request ! {Trace}
enrich (Request(priority, tagged)) = {
    let ignored = perform Trace.stage 3
    Request(priority, true)
}

publish_and_deliver : Request -> Result ! {Pipeline, Trace}
publish_and_deliver request = {
    let transformed = perform Pipeline.publish request
    let ignored = perform Trace.stage 4
    Delivered(transformed)
}

pipeline : Bool -> Result ! {Policy, Trace}
pipeline include_enrichment = hook Pipeline {
    register Pipeline normalize {
        register Pipeline check_policy {
            match include_enrichment {
                true => register Pipeline enrich {
                    publish_and_deliver (Request(0, false))
                }
                false => publish_and_deliver (Request(0, false))
            }
        }
    }
}

pub run : (Bool, Bool) -> (Result, Steps)
run (allow, include_enrichment) = handle {
    let result = handle (pipeline include_enrichment) with Policy {
        check request => match allow {
            true => resume ()
            false => {
                let ignored = discard
                Rejected
            }
        }
    }
    (result, End)
} with Trace {
    stage digit => {
        let (result, later) = resume ()
        (result, Step(digit, later))
    }
}

pub type CompletionError =
    AuditFailed(Int)
    | SummaryFailed(Int)

pub type CloseResult<E> =
    Closed
    | CloseFailed(E)

pub type Failures<E> =
    NoFailures
    | FailureItem(E, Failures<E>)

pub type Report<A, E> = Report(A, Failures<E>)

pub effect CleanupFailure<E> {
    report : E -> Unit
}

pub report_close<E> : CloseResult<E> -> Unit ! {CleanupFailure<E>}
report_close result = match result {
    Closed => ()
    CloseFailed(error) => perform CleanupFailure<E>.report error
}

pub collect<A, E, R : EffectRow> : (
    Unit -> A ! {CleanupFailure<E> | R}
) -> Report<A, E> ! {| R}
collect calculation = handle {
    let value = calculation(())
    Report(value, NoFailures)
} with CleanupFailure<E> {
    report error => match (resume ()) {
        Report(value, errors) => Report(value, FailureItem(error, errors))
    }
}

import reporting as Reporting

pub type Command =
    Add(Int)
    | Reject(Int)

pub type Commands =
    End
    | Next(Command, Commands)

pub type PrimaryError =
    RejectedCommand(Int)
    | CancelledBatch

pub type Outcome =
    Success(Int)
    | Failed(PrimaryError)

pub type Execution = Execution(Outcome, Commands)

run_from : (Int, Commands) -> Execution
run_from (total, End) = Execution(Success(total), End)
run_from (total, Next(Add(amount), later)) = {
    match run_from(total + amount, later) {
        Execution(outcome, executed) => Execution(
            outcome, Next(Add(amount), executed)
        )
    }
}
run_from (total, Next(Reject(code), later)) = {
    Execution(Failed(RejectedCommand(code)), Next(Reject(code), End))
}

pub run : Commands -> Execution
run commands = run_from(0, commands)

pub type Decision =
    Accepted(Int)
    | PrimaryFailed(PrimaryError)
    | CompletionFailed(Reporting.CompletionError)

pub decide : Reporting.Report<Execution, Reporting.CompletionError> -> Decision
decide report = {
    let Reporting.Report(Execution(outcome, executed), errors) = report
    match outcome {
        Failed(error) => PrimaryFailed(error)
        Success(total) => match errors {
            Reporting.NoFailures => Accepted(total)
            Reporting.FailureItem(first, later) => CompletionFailed(first)
        }
    }
}

